 if($a==='manual_assign'){$tripId=trim((string)$_POST['trip_id']);$driverId=trim((string)$_POST['driver_id']);$pdo->beginTransaction();$q=$pdo->prepare("SELECT status FROM trips WHERE id=? FOR UPDATE");$q->execute([$tripId]);$status=$q->fetchColumn();if(!in_array($status,['requested','searching'],true))throw new RuntimeException('این سفر دیگر قابل تخصیص نیست.');$d=$pdo->prepare("SELECT COUNT(*) FROM drivers WHERE user_id=? AND status='approved'");$d->execute([$driverId]);if((int)$d->fetchColumn()!==1)throw new RuntimeException('راننده تأییدشده نیست.');$u=$pdo->prepare("UPDATE trips SET driver_id=?,status='driver_assigned',accepted_at=NOW(),version=version+1 WHERE id=? AND driver_id IS NULL AND status IN('requested','searching')");$u->execute([$driverId,$tripId]);if($u->rowCount()!==1)throw new RuntimeException('تخصیص همزمان انجام شد؛ صفحه را تازه کنید.');$pdo->prepare('UPDATE trip_offers SET accepted=0,responded_at=COALESCE(responded_at,NOW()) WHERE trip_id=? AND driver_id<>? AND accepted IS NULL')->execute([$tripId,$driverId]);$pdo->commit();rado_platform_notify($pdo,$driverId,'سفر توسط اپراتور تخصیص یافت','مدیریت RADO یک سفر را به شما اختصاص داد.','trip_assigned',['trip_id'=>$tripId]);rado_platform_event($pdo,'trip:'.$tripId,'manual_assigned',['driver_id'=>$driverId]);adminAudit2($pdo,$a,'trip',$tripId,['driver_id'=>$driverId]);$msg='راننده به سفر تخصیص یافت.';}
 if($a==='cancel_trip'){$tripId=trim((string)$_POST['trip_id']);$reason=mb_substr(trim((string)($_POST['reason']??'')),0,500,'UTF-8');$refund=max(0,(int)($_POST['refund_amount']??0));$pdo->beginTransaction();$q=$pdo->prepare('SELECT * FROM trips WHERE id=? FOR UPDATE');$q->execute([$tripId]);$trip=$q->fetch();if(!is_array($trip)||in_array($trip['status'],['completed','cancelled_by_admin','cancelled_by_passenger','cancelled_by_driver','expired'],true))throw new RuntimeException('سفر قابل لغو نیست.');$pdo->prepare("UPDATE trips SET status='cancelled_by_admin',cancelled_at=NOW(),version=version+1 WHERE id=?")->execute([$tripId]);$pdo->prepare("INSERT INTO trip_cancellation_events(trip_id,actor_user_id,actor_role,reason_code,reason_text,refund_amount) VALUES(?,?,'admin','admin_cancel',?,?)")->execute([$tripId,(string)$_SESSION['admin_id'],$reason?:null,$refund]);if($refund>0){$key='refund:trip:'.$tripId.':admin';$ins=$pdo->prepare("INSERT IGNORE INTO ledger_entries(user_id,trip_id,entry_type,amount,idempotency_key,metadata_json) VALUES(?,?,'refund',?,?,?)");$ins->execute([(string)$trip['passenger_id'],$tripId,$refund,$key,json_encode(['reason'=>$reason],JSON_UNESCAPED_UNICODE)]);if($ins->rowCount()===1)rado_sync_wallet_cache($pdo,(string)$trip['passenger_id']);$pdo->prepare("INSERT IGNORE INTO refunds(trip_id,user_id,amount,reason,status,idempotency_key,created_by_admin_id,completed_at) VALUES(?,?,?,?,'completed',?,?,NOW())")->execute([$tripId,(string)$trip['passenger_id'],$refund,$reason?:null,$key,(string)$_SESSION['admin_id']]);}$pdo->commit();if(!empty($trip['driver_id']))rado_platform_notify($pdo,(string)$trip['driver_id'],'سفر لغو شد','این سفر توسط مدیریت RADO لغو شد.','trip_cancelled',['trip_id'=>$tripId]);rado_platform_notify($pdo,(string)$trip['passenger_id'],'سفر لغو شد','سفر شما توسط پشتیبانی RADO لغو شد.','trip_cancelled',['trip_id'=>$tripId]);adminAudit2($pdo,$a,'trip',$tripId,['refund'=>$refund,'reason'=>$reason]);$msg='سفر لغو شد'.($refund>0?' و بازپرداخت