 if($a==='corporate_member'){$corp=(int)$_POST['corporate_id'];$phone=preg_replace('/\D+/','',(string)$_POST['phone']);if($corp<1||strlen($phone)<10)throw new RuntimeException('اطلاعات عضویت ناقص است.');$q=$pdo->prepare("SELECT id FROM users WHERE phone=? AND role='passenger' LIMIT 1");$q->execute([$phone]);$uid=$q->fetchColumn();if($uid===false){$uid=rado_uuid4();$pdo->prepare("INSERT INTO users(id,phone,role,full_name,is_active) VALUES(?,?,'passenger','مسافر سازمانی',1)")->execute([$uid,$phone]);}$pdo->prepare('INSERT INTO corporate_members(corporate_account_id,user_id,employee_code,monthly_limit,active) VALUES(?,?,?,?,1) ON DUPLICATE KEY UPDATE employee_code=VALUES(employee_code),monthly_limit=VALUES(monthly_limit),active=1')->execute([$corp,$uid,trim((string)($_POST['employee_code']??''))?:null,($_POST['monthly_limit']??'')!==''?(int)$_POST['monthly_limit']:null]);adminAudit2($pdo,$a,'corporate_member',$corp.':'.$uid);$msg='عضو سازمانی ذخیره شد.';}
 if($a==='document_status'){$id=(int)$_POST['id'];$status=(string)$_POST['status'];if(!in_array($status,['approved','rejected','pending'],true))throw new RuntimeException('وضعیت مدرک نامعتبر است.');$pdo->prepare('UPDATE driver_documents SET status=?,note=? WHERE id=?')->execute([$status,mb_substr(trim((string)($_POST['note']??'')),0,400,'UTF-8')?:null,$id]);adminAudit2($pdo,$a,'driver_document',(string)$id,['status'=>$status]);$msg='وضعیت مدرک بروزرسانی شد.';}
 if($a==='service_type'){$key=preg_replace('/[^a-z0-9_-]/i','',(string)$_POST['key']);$title=trim((string)$_POST['title']);$mult=max(.1,(float)$_POST['multiplier']);if($key===''||$title==='')throw new RuntimeException('سرویس نامعتبر است.');$pdo->prepare('INSERT INTO service_types(service_key,title,fare_multiplier,active) VALUES(?,?,?,1) ON DUPLICATE KEY UPDATE title=VALUES(title),fare_multiplier=VALUES(fare_multiplier),active=1')->execute([$key,$title,$mult]);rado_set_setting($pdo,'service_type_'.$key.'_multiplier',(string)$mult);$msg='نوع سرویس ذخیره شد.';}
