$active=$pdo->query("SELECT t.id,t.status,t.pickup_label,t.destination_label,t.estimated_fare,t.requested_at,t.driver_id,du.full_name driver_name FROM trips t LEFT JOIN users du ON du.id=t.driver_id WHERE t.status IN('requested','searching','driver_assigned','driver_arriving','arrived','in_progress') ORDER BY t.requested_at DESC LIMIT 100")->fetchAll();$drivers=$pdo->query("SELECT d.user_id,u.full_name,d.plate_number,p.is_online,p.latitude,p.longitude,p.last_seen_at FROM drivers d JOIN users u ON u.id=d.user_id LEFT JOIN driver_presence p ON p.driver_id=d.user_id WHERE d.status='approved' ORDER BY p.is_online DESC,p.last_seen_at DESC LIMIT 200")->fetchAll();$corps=$pdo->query('SELECT id,title FROM corporate_accounts WHERE active=1 ORDER BY title')->fetchAll();$docs=$pdo->query("SELECT dd.*,u.full_name FROM driver_documents dd JOIN users u ON u.id=dd.driver_id ORDER BY FIELD(dd.status,'pending','expired','rejected','approved'),dd.created_at DESC LIMIT 100")->fetchAll();$services=$pdo->query('SELECT * FROM service_types ORDER BY sort_order,title')->fetchAll();
